"""
KPI Library — real-data intelligence store for top 25 accounting, banking, and
private wealth firms. All figures sourced from 2024 public filings, earnings
releases, and verified industry reports.

50 KPIs per firm across: revenue · profitability · capital · aum · efficiency
                          workforce · valuation · geography
"""
import json
from datetime import datetime, timezone
from typing import Optional
from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel
from sqlalchemy import Column, Integer, String, Numeric, Boolean, DateTime, Text, func
from sqlalchemy.orm import Session

from backend.database import get_db, Base

router = APIRouter(prefix="/api/kpi-library", tags=["kpi-library"])


# ─── ORM Model ───────────────────────────────────────────────────────────────

class KPIEntry(Base):
    __tablename__ = "kpi_library"
    id            = Column(Integer, primary_key=True, autoincrement=True)
    firm_name     = Column(String(120), nullable=False, index=True)
    firm_type     = Column(String(30), nullable=False, index=True)
    sector_rank   = Column(Integer)
    ticker        = Column(String(10))
    hq            = Column(String(80))
    kpi_name      = Column(String(100), nullable=False)
    kpi_value     = Column(Numeric(20, 4))
    kpi_display   = Column(String(40))
    kpi_unit      = Column(String(30))
    kpi_category  = Column(String(40), index=True)
    fiscal_year   = Column(Integer, default=2024)
    source        = Column(String(200))
    yoy_change_pct= Column(Numeric(8, 2))
    notes         = Column(Text)
    is_verified   = Column(Boolean, default=True)
    ingested_at   = Column(DateTime, default=lambda: datetime.now(timezone.utc))


def _serialize(k: KPIEntry) -> dict:
    return {
        "id": k.id, "firm_name": k.firm_name, "firm_type": k.firm_type,
        "sector_rank": k.sector_rank, "ticker": k.ticker, "hq": k.hq,
        "kpi_name": k.kpi_name, "kpi_value": float(k.kpi_value) if k.kpi_value else None,
        "kpi_display": k.kpi_display, "kpi_unit": k.kpi_unit,
        "kpi_category": k.kpi_category, "fiscal_year": k.fiscal_year,
        "source": k.source, "yoy_change_pct": float(k.yoy_change_pct) if k.yoy_change_pct else None,
        "notes": k.notes, "is_verified": k.is_verified,
        "ingested_at": k.ingested_at.isoformat() if k.ingested_at else None,
    }


