# ─── Routes ──────────────────────────────────────────────────────────────────

@router.post("/seed", status_code=201)
def seed_kpi_library(db: Session = Depends(get_db)):
    """Seed the KPI library with 50 KPIs per firm across 25 firms."""
    existing = db.query(KPIEntry).count()
    if existing > 0:
        return {"seeded": 0, "total": existing, "message": "KPI library already seeded — use /reseed to force"}

    entries = [KPIEntry(**row) for row in SEED_DATA]
    db.add_all(entries)
    db.commit()
    return {
        "seeded": len(entries),
        "total": len(entries),
        "firms": len(set(e.firm_name for e in entries)),
        "message": f"Seeded {len(entries)} KPIs across {len(set(e.firm_name for e in entries))} firms",
    }


@router.post("/reseed", status_code=200)
def reseed_kpi_library(db: Session = Depends(get_db)):
    """Clear and re-seed the KPI library with the full 50-KPI dataset."""
    deleted = db.query(KPIEntry).delete()
    db.commit()
    entries = [KPIEntry(**row) for row in SEED_DATA]
    db.add_all(entries)
    db.commit()
    firms = len(set(e.firm_name for e in entries))
    return {
        "deleted": deleted,
        "seeded": len(entries),
        "firms": firms,
        "kpis_per_firm": len(entries) // firms if firms else 0,
        "message": f"Re-seeded {len(entries)} KPIs ({len(entries)//firms} per firm) across {firms} firms",
    }


@router.get("")
def list_kpis(
    firm_type: Optional[str] = Query(None),
    firm_name: Optional[str] = Query(None),
    kpi_category: Optional[str] = Query(None),
    q: Optional[str] = Query(None),
    limit: int = Query(500, le=2000),
    db: Session = Depends(get_db),
):
    """Return KPI entries with optional filters."""
    query = db.query(KPIEntry)
    if firm_type:
        query = query.filter(KPIEntry.firm_type == firm_type)
    if firm_name:
        query = query.filter(KPIEntry.firm_name.ilike(f"%{firm_name}%"))
    if kpi_category:
        query = query.filter(KPIEntry.kpi_category == kpi_category)
    if q:
        query = query.filter(
            (KPIEntry.firm_name.ilike(f"%{q}%")) |
            (KPIEntry.kpi_name.ilike(f"%{q}%")) |
            (KPIEntry.kpi_display.ilike(f"%{q}%"))
        )
    entries = query.order_by(KPIEntry.firm_type, KPIEntry.sector_rank, KPIEntry.kpi_category).limit(limit).all()

    total = db.query(KPIEntry).count()
    firm_count = db.query(func.count(func.distinct(KPIEntry.firm_name))).scalar()
    type_counts = {
        t: db.query(func.count(func.distinct(KPIEntry.firm_name)))
              .filter(KPIEntry.firm_type == t).scalar()
        for t in ["banking", "private_wealth", "accounting"]
    }

    return {
        "entries": [_serialize(k) for k in entries],
        "count": len(entries),
        "summary": {
            "total_kpis": total,
            "total_firms": firm_count,
            "type_breakdown": type_counts,
        },
    }


@router.get("/firms")
def list_firms(db: Session = Depends(get_db)):
    """Return all unique firms with their metadata."""
    rows = db.query(
        KPIEntry.firm_name, KPIEntry.firm_type, KPIEntry.sector_rank,
        KPIEntry.ticker, KPIEntry.hq,
        func.count(KPIEntry.id).label("kpi_count"),
    ).group_by(
        KPIEntry.firm_name, KPIEntry.firm_type, KPIEntry.sector_rank,
        KPIEntry.ticker, KPIEntry.hq,
    ).order_by(KPIEntry.firm_type, KPIEntry.sector_rank).all()

    return {"firms": [
        {"firm_name": r.firm_name, "firm_type": r.firm_type, "sector_rank": r.sector_rank,
         "ticker": r.ticker, "hq": r.hq, "kpi_count": r.kpi_count}
        for r in rows
    ]}


@router.get("/firm/{firm_name}")
def get_firm(firm_name: str, db: Session = Depends(get_db)):
    """Return all KPIs for a specific firm."""
    entries = db.query(KPIEntry).filter(
        KPIEntry.firm_name.ilike(f"%{firm_name}%")
    ).order_by(KPIEntry.kpi_category).all()
    if not entries:
        raise HTTPException(404, f"No KPIs found for firm: {firm_name}")
    return {
        "firm_name": entries[0].firm_name,
        "firm_type": entries[0].firm_type,
        "ticker": entries[0].ticker,
        "hq": entries[0].hq,
        "kpis": [_serialize(k) for k in entries],
    }


@router.get("/categories")
def get_categories(db: Session = Depends(get_db)):
    """Return distinct KPI categories with counts."""
    rows = db.query(KPIEntry.kpi_category, func.count(KPIEntry.id).label("count"))\
             .group_by(KPIEntry.kpi_category).order_by(func.count(KPIEntry.id).desc()).all()
    return {"categories": [{"category": r.kpi_category, "count": r.count} for r in rows]}


@router.get("/compare")
def compare_firms(
    firms: str = Query(..., description="Comma-separated firm names"),
    kpi_category: Optional[str] = Query(None),
    db: Session = Depends(get_db),
):
    """Compare KPIs across multiple firms side-by-side."""
    firm_list = [f.strip() for f in firms.split(",") if f.strip()]
    result = {}
    for firm in firm_list:
        q = db.query(KPIEntry).filter(KPIEntry.firm_name.ilike(f"%{firm}%"))
        if kpi_category:
            q = q.filter(KPIEntry.kpi_category == kpi_category)
        entries = q.all()
        result[firm] = [_serialize(e) for e in entries]
    return {"comparison": result, "firms": firm_list}
